  ["FactionDescription:21"] = { "Questa fiorente città di mare è amministrata dal Barone Revilgaz degli Incursori di Acquanera. Fa parte del Cartello degli Spargifumo ed è nemica mortale dei Bucanieri Velerosse.", 0x7e9b81b0, "." },
  ["FactionDescription:270"] = { "Questi Troll sono giunti sull'Isola di Yojamba nel tentativo di cercare aiuto per affrontare il Dio del Sangue e i suoi sacerdoti Atal'ai a Zul'gurub.", 0x407992c7, "." },
  ["FactionDescription:349"] = { "Questa gilda di ladri e assassini accetta tra le proprie file soltanto coloro che sono dotati di eccezionali capacità. Nemici giurati della Lega dei Tagliagole.", 0xe15addc5, "." },
  ["FactionDescription:369"] = { "Capitale del Cartello degli Spargifumo e patria dei migliori ingegneri, alchimisti e mercanti Goblin.", 0x6bc27bf5, "." },
  ["FactionDescription:47"] = { "Questa capitale dell'Alleanza è l'orgoglio dei Nani di Dun Morogh, ed è la dimora dei Re dei Nani.", 0x7338a738, "." },
  ["FactionDescription:470"] = { "Questa cittadina Goblin, controllata dal Cartello degli Spargifumo, rappresenta un porto sicuro per tutti coloro che desiderano commerciare nelle Savane.", 0xd92b7fb2, "." },
  ["FactionDescription:510"] = { "I Profanatori stanno cercando di impossessarsi delle preziose risorse del Bacino di Arathi per conto dell'Orda.", 0x0a18bac0, "." },
  ["FactionDescription:529"] = { "Un'organizzazione dedita alla protezione di Azeroth dalla minaccia del Flagello. Roccaforti dell'Alba d'Argento occupano le Terre Infette Orientali e Occidentali.", 0x4113163d, "." },
  ["FactionDescription:530"] = { "Questa tribù di Troll in esilio ha unito le proprie forze a quelle di Thrall e dell'Orda. Durotar è ora la loro patria, che condividono insieme ai loro alleati Orchi.", 0x3ea5477c, "." },
  ["FactionDescription:577"] = { "Questo insediamento commerciale è gestito dai Goblin del Cartello degli Spargifumo e si trova sul crocevia tra le principali vie commerciali di Fontefredda.", 0xa62dc357, "." },
  ["FactionDescription:589"] = { "Questo piccolo gruppo solitario di Elfi della Notte alleva e addestra le Fiere Glaciali nell'area di Fontefredda.", 0x4f149356, "." },
  ["FactionDescription:59"] = { "I Nani della Fratellanza del Torio dimostrano grandi competenze nella forgiatura di oggetti magici e sono decisi a carpire tutti i segreti del Massiccio Roccianera.", 0xd74f4abb, "." },
  ["FactionDescription:609"] = { "I Druidi del Circolo Cenariano sono i guardiani della natura e dominano le tranquille terre di Radaluna.", 0x09a580e2, "." },
  ["FactionDescription:68"] = { "Guidati da Sylvanas Ventolesto, i Reietti hanno stretto una delicata alleanza con l'Orda e hanno costruito la loro capitale nelle profondità delle Rovine di Lordaeron.", 0xde70e660, "." },
  ["FactionDescription:70"] = { "Un'organizzazione criminale gestita principalmente da Umani che opera principalmente tra le Montagne d'Alterac e le Alture di Colletorto.", 0x039ecfd7, "." },
  ["FactionDescription:729"] = { "Il Clan Lupi Bianchi sta cercando di scacciare i Nani del Clan Piccatonante dalla Valle d'Alterac.", 0xb1085726, "." },
  ["FactionDescription:730"] = { "I Nani Piccatonante hanno consolidato la loro dimora nella Valle d'Alterac, dove si trovano in continua lotta contro gli Orchi Lupi Bianchi.", 0xf10b0cba, "." },
  ["FactionDescription:749"] = { "Questi elementali hanno preso dimora nelle isole orientali di Azshara. Sono nemici giurati delle armate di Ragnaros.", 0x6fb36621, "." },
  ["FactionDescription:76"] = { "Fondata da Thrall, la capitale dell'Orda è la patria dei valorosi clan di Orchi che abitano Durotar.", 0x86291572, "." },
  ["FactionDescription:809"] = { "Costituiscono ciò che resta di un gruppo di potenti Elfi che abitavano Maglio Infausto; ancora oggi sono considerati grandi saggi e detentori di incredibili segreti.", 0x63e9a14a, "." },
  ["FactionDescription:87"] = { "Questi spietati corsari sono la rovina dei commerci marittimi. Nemici giurati dei Goblin della Baia del Bottino.", 0x7ad652c1, "." },
  ["FactionDescription:889"] = { "Feroci Orchi del Clan Cantaguerra, in continua battaglia contro le Sentinelle Alargentea nella Forra dei Cantaguerra.", 0xdfb1cd3c, "." },
  ["FactionDescription:890"] = { "Fedeli difensori di Valtetra, in continua battaglia con i Predoni Cantaguerra nella Forra dei Cantaguerra.", 0xa1c33f03, "." },
  ["FactionDescription:910"] = { "Discendenti dello Stormo dei Draghi di Bronzo, sono i guardiani del tempo e sono noti per interessarsi ben poco delle razze mortali.", 0x83782a84, "." },
  ["FactionDescription:92"] = { "Questi Centauri si sono insediati nelle regioni meridionali di Desolanda. Nemici mortali dei Centauri Magram.", 0x1b4b2304, "." },
  ["FactionDescription:93"] = { "Questi Centauri si sono insediati nelle regioni orientali di Desolanda. Nemici mortali dei Centauri Gelkis.", 0xc63dbc46, "." },
})
